class Solution:
    def findMin(self, nums: List[int]) -> int:
        smallest = nums[0]
        for num in nums:
            if num < smallest:
                smallest = num
        return smallest

class Solution:
    def findMin(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:
                lo = mid + 1
            else:
                hi = mid
        return nums[lo]
